import type { LocationInput, WeatherPeriod, CurrentWeather } from './types.js';

type NwsPoint = {
	properties: {
		forecast: string;
		relativeLocation?: {
			properties?: {
				city?: string;
				state?: string;
			};
		};
	};
};

type NwsForecast = {
	properties: {
		periods: WeatherPeriod[];
	};
};

const headers = {
	Accept: 'application/geo+json',
	'User-Agent': 'wxcn/0.1 (https://github.com/wxcn/wxcn)'
};

export async function fetchWeatherForecast(location: LocationInput): Promise<WeatherPeriod[]> {
	const point = await fetch(
		`https://api.weather.gov/points/${location.latitude.toFixed(4)},${location.longitude.toFixed(4)}`,
		{ headers }
	);

	if (!point.ok) {
		throw new Error(`NWS point lookup failed with ${point.status}`);
	}

	const pointData = (await point.json()) as NwsPoint;
	const forecast = await fetch(pointData.properties.forecast, { headers });

	if (!forecast.ok) {
		throw new Error(`NWS forecast lookup failed with ${forecast.status}`);
	}

	const forecastData = (await forecast.json()) as NwsForecast;
	return forecastData.properties.periods;
}

/** Deterministic Austin fixtures for previews; not live observations. */
export const sampleWeather: WeatherPeriod[] = [
	['Today', 92, 'Mostly Sunny', true],
	['Tonight', 74, 'Partly Cloudy', false],
	['Monday', 94, 'Sunny', true],
	['Monday night', 75, 'Mostly Clear', false],
	['Tuesday', 89, 'Chance of Rain', true],
	['Tuesday night', 72, 'Partly Cloudy', false],
	['Wednesday', 90, 'Sunny', true]
].map(([name, temperature, shortForecast, isDaytime], index) => ({
	name: name as string,
	temperature: temperature as number,
	shortForecast: shortForecast as string,
	isDaytime: isDaytime as boolean,
	startTime: `2026-09-${String(6 + Math.floor(index / 2)).padStart(2, '0')}T${index % 2 ? '19' : '07'}:00:00-05:00`,
	temperatureUnit: 'F',
	windSpeed: '5 to 10 mph',
	windDirection: 'S',
	detailedForecast: `${shortForecast}. South wind 5 to 10 mph.`
}));

export function convertWindSpeed(speed: string, unit: 'mph' | 'km/h' | 'm/s' | 'knots' = 'mph') {
	const factors = { mph: 0.44704, 'km/h': 1 / 3.6, 'm/s': 1, knots: 0.514444 };
	const source = speed.match(/mph|km\/h|m\/s|knots/);
	if (!source) return speed;
	return speed
		.replace(/\d+(?:\.\d+)?/g, (n) =>
			String(Math.round((Number(n) * factors[source[0] as keyof typeof factors]) / factors[unit]))
		)
		.replace(source[0], unit);
}

export const sampleCurrentWeather: CurrentWeather = {
	...sampleWeather[0],
	name: 'Now',
	temperature: 86,
	observedAt: '2026-09-06T16:00:00-05:00',
	startTime: '2026-09-06T16:00:00-05:00',
	highToday: 88
};

export type ForecastEntry = { time: number; label: string; summary: string; details: string };
export type ForecastDay = { key: string; label: string; entries: ForecastEntry[] };

/** Group supplied periods in the location's calendar, without inventing missing days. */
export function forecastDays(entries: ForecastEntry[], timeZone: string): ForecastDay[] {
	const key = new Intl.DateTimeFormat('en-CA', {
		timeZone,
		year: 'numeric',
		month: '2-digit',
		day: '2-digit'
	});
	const label = new Intl.DateTimeFormat('en-US', {
		timeZone,
		weekday: 'short',
		month: 'short',
		day: 'numeric'
	});
	const days = new Map<string, ForecastDay>();
	for (const entry of entries
		.filter((e) => Number.isFinite(e.time))
		.toSorted((a, b) => a.time - b.time)) {
		const id = key.format(entry.time);
		if (!days.has(id)) days.set(id, { key: id, label: label.format(entry.time), entries: [] });
		days.get(id)!.entries.push(entry);
	}
	return [...days.values()].slice(0, 7);
}

export type CardSize = 'sm' | 'default' | 'lg';
export type CardDensity = 'compact' | 'comfortable';
export type ForecastType = 'summary' | 'detailed' | 'simple';
export type IconSet = 'hugeicons' | 'phosphor-svelte' | 'lucide' | 'tabler' | 'remix';
export type WeatherUnit = 'fahrenheit' | 'celsius';
export type TideUnit = 'ft' | 'meter';

export type LocationInput = {
	label?: string;
	latitude: number;
	longitude: number;
	station?: string;
	timeZone?: string;
};

export type WeatherPeriod = {
	name: string;
	startTime: string;
	endTime?: string;
	temperature: number;
	temperatureUnit: string;
	windSpeed: string;
	windDirection: string;
	shortForecast: string;
	detailedForecast: string;
	isDaytime: boolean;
};

export type TidePrediction = {
	time: string;
	height: string;
	type: 'H' | 'L';
};

export type MoonForecast = {
	date: string;
	phaseName: string;
	/** Astronomical phase cycle: 0 new, 0.25 first quarter, 0.5 full. */
	phase?: number;
	illumination: number;
	age: number;
	nextFullMoon: string;
	nextNewMoon: string;
};

/** Feet above MLLW. Prefer ISO 8601 timestamps with an explicit offset. */
export type TidePoint = { time: string; height: string };
export type TideReading = TidePoint;

/** Current observed conditions; daily extrema use temperatureUnit and the location's calendar day. */
export type CurrentWeather = WeatherPeriod & {
	observedAt: string;
	highToday?: number;
	lowToday?: number;
};

export type WeatherBackground = 'none' | 'realistic' | 'dithered' | 'gradient';

import {
	Body,
	Equator,
	Horizon,
	Illumination,
	MoonPhase,
	Observer,
	SearchHourAngle,
	SearchRiseSet
} from 'astronomy-engine';

export type SkyPeriod = 'sunrise' | 'midday' | 'sunset' | 'night';
export type SkyBody = { azimuth: number; altitude: number; visible: boolean; x: number; y: number };
export type SkyState = {
	at: number;
	period: SkyPeriod;
	isDaytime: boolean;
	sun: SkyBody;
	moon: SkyBody & {
		illumination: number;
		phase: number;
		phaseName: string;
		light: [number, number, number];
	};
};
const rad = Math.PI / 180;
const cache = new Map<string, SkyState>();
const phaseNames = [
	'New Moon',
	'Waxing Crescent',
	'First Quarter',
	'Waxing Gibbous',
	'Full Moon',
	'Waning Gibbous',
	'Last Quarter',
	'Waning Crescent'
];

// Fixed 360-degree panorama: N at both edges, E at 25%, S at 50%, W at 75%.
// Altitude maps from the horizon at 12% to the zenith at 88% of card height.
// Discs are enlarged for readability; coordinates retain their astronomical values.
function project(azimuth: number, altitude: number): SkyBody {
	return {
		azimuth,
		altitude,
		visible: altitude >= -0.2666,
		x: azimuth / 360,
		y: 0.12 + (altitude / 90) * 0.76
	};
}
function valid(latitude: number, longitude: number, at: number) {
	return (
		Number.isFinite(latitude) &&
		Math.abs(latitude) <= 90 &&
		Number.isFinite(longitude) &&
		Math.abs(longitude) <= 180 &&
		Number.isFinite(at) &&
		Math.abs(at) <= 8640000000000000
	);
}
export function getSkyState(latitude: number, longitude: number, at = Date.now()): SkyState | null {
	if (!valid(latitude, longitude, at)) return null;
	// Cards request positions once per minute; preserve an explicit event timestamp.
	const key = `${latitude}:${longitude}:${at}`;
	const cached = cache.get(key);
	if (cached) return cached;
	const date = new Date(at);
	const observer = new Observer(latitude, longitude, 0);
	function position(body: Body, instant = date) {
		const eq = Equator(body, instant, observer, true, true);
		return Horizon(instant, observer, eq.ra, eq.dec, 'normal');
	}
	const sunPosition = position(Body.Sun);
	const moonPosition = position(Body.Moon);
	const sun = project(sunPosition.azimuth, sunPosition.altitude);
	// Apparent upper solar limb at the horizon (refraction is applied by Horizon).
	const isDaytime = sun.altitude >= -0.2666;
	const rising = position(Body.Sun, new Date(at + 60000)).altitude > sun.altitude;
	const period: SkyPeriod =
		sun.altitude < -6 ? 'night' : sun.altitude <= 6 ? (rising ? 'sunrise' : 'sunset') : 'midday';
	const illumination = Illumination(Body.Moon, date).phase_fraction;
	const phase = MoonPhase(date) / 360;
	// Project the Sun onto the Moon's local horizon tangent plane. This gives the
	// illuminated limb its observer-relative tilt, including hemisphere differences.
	const sa = sun.azimuth * rad,
		sh = sun.altitude * rad;
	const ma = moonPosition.azimuth * rad,
		mh = moonPosition.altitude * rad;
	const sx = Math.cos(sh) * Math.sin(sa),
		sy = Math.sin(sh),
		sz = Math.cos(sh) * Math.cos(sa);
	const right = sx * Math.cos(ma) - sz * Math.sin(ma);
	const up =
		-sx * Math.sin(mh) * Math.sin(ma) + sy * Math.cos(mh) - sz * Math.sin(mh) * Math.cos(ma);
	const length = Math.hypot(right, up) || 1;
	const z = 2 * illumination - 1;
	const tangent = Math.sqrt(Math.max(0, 1 - z * z));
	const state: SkyState = {
		at,
		period,
		isDaytime,
		sun,
		moon: {
			...project(moonPosition.azimuth, moonPosition.altitude),
			illumination,
			phase,
			phaseName: phaseNames[Math.round(phase * 8) % 8],
			light: [(right / length) * tangent, (up / length) * tangent, z]
		}
	};
	if (cache.size >= 256) cache.delete(cache.keys().next().value!);
	cache.set(key, state);
	return state;
}

export function getSkyPreviewTime(
	latitude: number,
	longitude: number,
	at: number,
	period: SkyPeriod
): number | null {
	if (!valid(latitude, longitude, at)) return null;
	const observer = new Observer(latitude, longitude, 0);
	const start = new Date(at - 12 * 3600000);
	const event =
		period === 'sunrise' || period === 'sunset'
			? SearchRiseSet(Body.Sun, observer, period === 'sunrise' ? 1 : -1, start, 1)
			: SearchHourAngle(Body.Sun, observer, period === 'midday' ? 0 : 12, start).time;
	return event?.date.getTime() ?? null; // Polar day/night can have no rise or set.
}

import type { CurrentWeather, WeatherPeriod, WeatherUnit } from './types.js';
export function weatherTemperature(value: number, from: string, unit: WeatherUnit) {
	return Math.round(
		unit === 'celsius' && from === 'F'
			? ((value - 32) * 5) / 9
			: unit === 'fahrenheit' && from === 'C'
				? (value * 9) / 5 + 32
				: value
	);
}
export function weatherOutlook(
	current: CurrentWeather | null,
	forecast: WeatherPeriod[],
	unit: WeatherUnit,
	timeZone = 'UTC',
	at = Date.now()
) {
	const day = (time: string | number) =>
		new Intl.DateTimeFormat('en-CA', {
			timeZone,
			year: 'numeric',
			month: '2-digit',
			day: '2-digit'
		}).format(new Date(time));
	const today = day(at);
	const valid = forecast.filter(
		(p) =>
			Number.isFinite(p.temperature) &&
			Number.isFinite(Date.parse(p.startTime)) &&
			(!p.endTime || Date.parse(p.endTime) > at)
	);
	const highPeriod = valid.find((p) => p.isDaytime && day(p.startTime) === today);
	const lowPeriod = valid.find(
		(p) =>
			!p.isDaytime &&
			(day(p.startTime) === today ||
				(Date.parse(p.startTime) <= at && !!p.endTime && Date.parse(p.endTime) > at))
	);
	const observedHigh =
		current?.highToday === undefined
			? null
			: weatherTemperature(current.highToday, current.temperatureUnit, unit);
	const high = highPeriod
		? Math.max(
				weatherTemperature(highPeriod.temperature, highPeriod.temperatureUnit, unit),
				observedHigh ?? -Infinity
			)
		: observedHigh;
	const low = lowPeriod
		? weatherTemperature(lowPeriod.temperature, lowPeriod.temperatureUnit, unit)
		: null;
	const temp = current
		? weatherTemperature(current.temperature, current.temperatureUnit, unit)
		: null;
	const highReached =
		high !== null &&
		((observedHigh !== null && observedHigh >= high) || (temp !== null && temp >= high));
	let trend: string | null = null;
	if (temp !== null) {
		if (current?.isDaytime && high !== null && !highReached && temp < high)
			trend = `Going up to ${high}° today`;
		else if (low !== null && temp > low)
			trend = `Going down to ${low}° ${lowPeriod?.name.toLowerCase().includes('overnight') ? 'overnight' : 'tonight'}`;
	}
	return { high, low, trend, highReached };
}
